{
  "title": "The Mirror Rescue of the Broken City",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "A mapmaker unrolls the plan of a ruined city.",
      "visual_description": "Mara spreads a torn map on a crate beside a shattered fountain, brass compass spinning, ash drifting through orange dusk light.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The lamp warns of what waits inside the walls.",
      "visual_description": "A battered oil lamp held aloft, its single flame-eye narrowed, casting long warning shadows across the cracked city gates.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "A clockwork scout slips through the rubble.",
      "visual_description": "A small tin fox with a key-wind tail darts between collapsed market stalls, blue glass eyes catching firelight.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "The glass diver steps out of a broken window.",
      "visual_description": "A figure in a clear diving helmet emerges from a shattered shop window as if surfacing from water, coat shimmering with reflected city lights.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 5,
      "caption": "They find an official asleep on his ledger.",
      "visual_description": "A plump man slumped against a toll booth, ledger book under his cheek, stamped papers stuck to his sleeves, snoring beneath a torn royal banner.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "The lamp refuses to look toward the cursed tower.",
      "visual_description": "A twisted black tower leans against a green moon; the oil lamp turns its flame-eye away, sparks falling like tears onto cobblestones.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "Armored patrols march past in eerie silence.",
      "visual_description": "From a sewer grate's shadow, the tin fox watches polished boots and tasseled halberds tramp by, banners snapping overhead.",
      "characters": ["tin_fox", "glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "Mara plots a route through the mirror halls.",
      "visual_description": "Inside a collapsed barber shop, dozens of cracked mirrors reflect Mara's lamp-lit map as she traces a path with an inked finger.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 9,
      "caption": "The diver slips through a tall standing mirror.",
      "visual_description": "Glass diver wades waist-deep into a silvered mirror, ripples spreading outward, helmet glinting as the room behind reverses.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 10,
      "caption": "A magic door demands a name nobody remembers.",
      "visual_description": "An iron door etched with shifting runes blocks a marble corridor; the lamp's flame-eye flickers nervously while Mara presses her palm against the metal.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 11,
      "caption": "The tin fox finds the captive in a glass cell.",
      "visual_description": "Deep in a chandeliered hall, the clockwork fox peers through a tall bell-jar where a small figure sleeps in chains of light.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 12,
      "caption": "Rumors of something winged echo overhead.",
      "visual_description": "Massive scaled shadows pass over stained-glass skylights; Mara ducks, pressing the lamp to her chest as colored light slides across her face.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 13,
      "caption": "They drag the sleeping official along anyway.",
      "visual_description": "Glass diver and Mara haul the snoring man by his ankles down a tilted staircase, stamped papers fluttering behind like confetti.",
      "characters": ["glass_diver", "mara_the_cartographer", "sleeping_tax_collector"]
    },
    {
      "scene_number": 14,
      "caption": "The diver swims back through a window of rain.",
      "visual_description": "Rain pours sideways across a tall arched window; the diver dives through it carrying the captive bundled in a coat, droplets frozen mid-air.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "The lamp screams that the patrols have turned.",
      "visual_description": "The oil lamp's flame-eye flares red and wide, illuminating a courtyard where armored figures swivel in unison toward the rescuers.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 16,
      "caption": "The clockwork fox sets off a tower of bells.",
      "visual_description": "Tin fox leaps across a rope of bell-pulls, brass bells crashing into deafening chorus, sparks flying from its wound-up tail.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "They race for the bridge as the city burns behind.",
      "visual_description": "A long stone bridge stretches over a black river; Mara runs in front, glass diver behind with the captive, lamp swinging wildly, fox bounding ahead.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "Across the river, the lamp finally smiles.",
      "visual_description": "On the far bank at dawn, the group rests on mossy stones; the oil lamp's flame-eye softens to gold, the tax collector still snoring against the tin fox.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    }
  ]
}

